INSERT OR IGNORE INTO categories (id, slug, name, parent, description_html, second_html) VALUES
(2001, 'vibratory-na-dalkove-ovladani', 'Vibrátory na dálkové ovládání a přes aplikaci', 85,
 '<p>Vibrátory, vajíčka a kolíky, které ovládáte <strong>dálkovým ovladačem nebo aplikací v mobilu</strong>. Hodí se pro hru ve dvou, na rande i na vztah na dálku, kdy partner nastavuje intenzitu odkudkoli. Ceny porovnáváme u všech obchodů, se kterými spolupracujeme.</p>',
 '<h2>Ovladač, nebo aplikace?</h2><p>Dálkový ovladač funguje hned po vybalení a nepotřebuje telefon, jeho dosah je ale obvykle jen několik metrů. Pomůcky s aplikací (například Lovense nebo We-Vibe) se připojí přes Bluetooth a přes internet je může ovládat i partner v jiném městě. Aplikace navíc nabízí vlastní vibrační vzory, vibrace podle hudby nebo synchronizaci s druhou pomůckou.</p><h3>Na co se dívat při výběru</h3><ul><li><strong>Typ pomůcky</strong> – nejoblíbenější jsou <a href="/vibratory-do-kalhotek/">vibrátory do kalhotek</a> a <a href="/vibracni-vajicka/">vibrační vajíčka</a>, pro páry <a href="/parove-vibratory/">párové vibrátory</a>.</li><li><strong>Výdrž baterie</strong> – u nošení venku počítejte alespoň s hodinou provozu.</li><li><strong>Voděodolnost</strong> – usnadní čištění a umožní použití ve sprše.</li><li><strong>Materiál</strong> – tělově nezávadný silikon je příjemný a snadno se čistí.</li></ul><p>Stejný model se mezi obchody často liší i o stovky korun, proto u každého produktu najdete srovnání všech nabídek.</p>'),
(2002, 'eroticke-pomucky-pro-pary', 'Erotické pomůcky pro páry', 0,
 '<p>Pomůcky, které si užijete <strong>ve dvou</strong>: párové vibrátory, hračky na dálkové ovládání, erotické hry, masážní oleje i kondomy pro páry. Vybíráme z ověřených českých obchodů a u každého produktu porovnáváme ceny.</p>',
 '<h2>Jak vybrat první pomůcku pro pár</h2><p>Pokud spolu začínáte, sáhněte po něčem, co nikoho nepřekvapí příliš: <a href="/masazni-oleje-a-svicky/">masážní olej nebo svíčka</a>, <a href="/eroticke-hry-pro-dospele/">erotická hra</a> nebo menší vibrační kroužek. Odvážnější páry ocení <a href="/parove-vibratory/">párové vibrátory</a>, které se nosí během styku, nebo <a href="/vibratory-na-dalkove-ovladani/">vibrátory na dálkové ovládání</a>, kdy jeden z partnerů drží ovladač.</p><h3>Tipy</h3><ul><li>Vyberte pomůcku spolu – zvýšíte šanci, že se bude líbit oběma.</li><li>K silikonovým hračkám používejte <a href="/lubrikacni-gely-a-oleje-na-vodni-bazi/">lubrikant na vodní bázi</a>.</li><li>Na první zkoušku stačí levnější model, kvalitní značky se vyplatí, až víte, co vám vyhovuje.</li></ul>'),
(2003, 'eroticke-pomucky-pro-zeny', 'Erotické pomůcky pro ženy', 0,
 '<p>Přehled hraček <strong>pro ženy</strong> na jednom místě: tlakové stimulátory klitorisu, vibrátory na bod G, rabbit vibrátory, vibrační vajíčka a venušiny kuličky. U každého produktu vidíte ceny ze všech obchodů, se kterými spolupracujeme.</p>',
 '<h2>Podle čeho vybírat</h2><p><strong>Tlakové stimulátory</strong> (Satisfyer, Womanizer) pracují s pulzy vzduchu a nedotýkají se přímo klitorisu – pro mnoho žen jsou nejrychlejší cestou k orgasmu. <a href="/vibratory-na-bod-g/">Vibrátory na bod G</a> mají zahnutou špičku, <a href="/vibratory-s-vybezkem-na-klitoris/">rabbit vibrátory</a> stimulují zároveň vnitřně i klitoris.</p><h3>Pro zdraví i potěšení</h3><p><a href="/venusiny-kulicky/">Venušiny kuličky</a> pomáhají posilovat pánevní dno, <a href="/vibracni-vajicka/">vibrační vajíčka</a> jsou malá a diskrétní. Začínáte? Vyberte tišší model z měkkého silikonu, nabíjecí přes USB a voděodolný.</p>'),
(2004, 'eroticke-pomucky-pro-muze', 'Erotické pomůcky pro muže', 0,
 '<p>Pomůcky <strong>pro muže</strong>: masturbátory a umělé vaginy, erekční kroužky, návleky, vakuové pumpy na penis i stimulátory prostaty. Ceny porovnáváme z ověřených českých obchodů, nakupujete přímo u prodejce.</p>',
 '<h2>Co vybrat</h2><p><a href="/umele-vaginy-a-masturbatory/">Masturbátory</a> jsou nejoblíbenější volbou – od jednorázových Tenga vajíček po Fleshlight a automatické modely. <a href="/erekcni-krouzky-na-penis-a-varlata/">Erekční kroužky</a> pomáhají udržet erekci a některé vibrují pro oba partnery. <a href="/masaz-prostaty/">Stimulátory prostaty</a> cílí na mužský bod G a <a href="/vakuove-pumpy-pro-muze-na-penis/">vakuové pumpy</a> zlepšují prokrvení.</p><h3>Tipy</h3><ul><li>K masturbátorům používejte lubrikant na vodní bázi, silikonový může materiál poškodit.</li><li>Kroužek nenoste déle než 20–30 minut.</li><li>Po použití pomůcku umyjte a nechte vyschnout.</li></ul>'),
(2005, 'nafukovaci-dilda-a-koliky', 'Nafukovací dilda a kolíky', 109,
 '<p>Dilda a anální kolíky, které se po zavedení <strong>nafouknou pumpičkou</strong> a postupně zvětší objem. Vhodné pro pokročilé, kteří chtějí velikost ovládat sami. Ceny porovnáváme u ověřených obchodů.</p>',
 '<h2>Jak na nafukovací pomůcky</h2><p>Začněte s pomůckou vyfouknutou a nafukujte po malých krocích – tlak se dá kdykoli uvolnit ventilem. Používejte dostatek <a href="/analni-lubrikacni-gely-a-oleje/">lubrikantu</a> a vybírejte modely z tělově nezávadného latexu nebo silikonu. Pro začátek je lepší menší <a href="/analni-koliky/">anální kolík</a> bez pumpičky.</p>'),
(2006, 'analni-koliky-s-prisavkou', 'Anální kolíky s přísavkou', 172,
 '<p>Anální kolíky se <strong>silnou přísavkou</strong>, které připevníte na hladkou podložku, zeď ve sprše nebo podlahu. Ruce zůstanou volné a polohu si zvolíte sami. Ceny ze všech obchodů najdete u každého produktu.</p>',
 '<h2>Na co si dát pozor</h2><p>Přísavka drží jen na hladkém a čistém povrchu (sklo, dlažba, laminát). Kolík musí mít rozšířenou základnu, aby nevklouzl celý dovnitř. Používejte <a href="/analni-lubrikacni-gely-a-oleje/">anální lubrikant</a> – k silikonovým kolíkům na vodní bázi. Podobné pomůcky najdete i mezi <a href="/dilda-s-prisavkou/">dildy s přísavkou</a>.</p>');

